void setup() {
  Serial.begin(9600);
  Serial.println("Hello! I'm ChatBot. Say hello, or ask me for a joke.");
}

void loop() {
  if (Serial.available() > 0) {
    String message = Serial.readStringUntil('\n');
    message.trim();
    message.toLowerCase();

    if (message == "hello" || message == "hi") {
      Serial.println("Hi there! Nice to meet you.");
    } else if (message == "how are you") {
      Serial.println("I'm feeling electric!");
    } else if (message == "joke") {
      Serial.println("Why did the LED go to school? To get brighter!");
    } else {
      Serial.println("I don't understand that yet. Try: hello, how are you, joke");
    }
  }
}
